class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        pq = [(moveTime[0][0], 0, 0)]  # (time, row, col)
        visited = set()

        while pq:
            current_time, row, col = heappop(pq)

            if (row, col) in visited:
                continue

            visited.add((row, col))

            if row == n - 1 and col == m - 1:
                return max(current_time, moveTime[row][col])

            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc

                if 0 <= new_row < n and 0 <= new_col < m:
                    next_time = max(current_time, moveTime[row][col]) + 1
                    heappush(pq, (next_time, new_row, new_col))

        return -1  # In case there's no path, though the problem guarantees there is one
