            if nums[start] != 0:
                continue

            left = start
            right = start
            direction = 1  # 1 for right, -1 for left
            steps = 0

            while True:
                if direction == 1:
                    right += 1
                else:
                    left -= 1

                if right >= n or left < 0:
                    break

                if nums[right] == 0:
                    steps += 1
                elif nums[right] > 0:
                    nums[right] -= 1
                    direction *= -1
                    steps += 1

                if nums[left] == 0:
                    steps += 1
                elif nums[left] > 0:
                    nums[left] -= 1
                    direction *= -1
                    steps += 1

            if sum(nums) == 0:
                result += 1

