class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        # Build the graph
        graph = [[] for _ in range(len(edges) + 1)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Function to perform DFS and calculate the maximum sum of weights
        def dfs(node, parent):
            max_weights = []
            total_sum = 0
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    child_sum, child_max_weight = dfs(neighbor, node)
                    total_sum += child_sum
                    heapq.heappush(max_weights, child_max_weight)
                    if len(max_weights) > k:
                        total_sum -= heapq.heappop(max_weights)

            if not max_weights:
                return total_sum, 0

            return total_sum, max(sum(max_weights), max_weights[0])

        # Start DFS from node 0
        return dfs(0, -1)[0]
