                        dp[i][j][k] = max(dp[i+1][j][k], dp[i+1][j+1][k], dp[i][j+1][k]) + fruits[i][j]
                    elif k == 1:
                        dp[i][j][k] = max(dp[i+1][j-1][k], dp[i+1][j][k], dp[i+1][j+1][k]) + fruits[i][j]
                    else:
                        dp[i][j][k] = max(dp[i-1][j+1][k], dp[i][j+1][k], dp[i+1][j+1][k]) + fruits[i][j]

