class Solution:
    def smallestNumber(self, n: int) -> int:
        # If n is already a power of two, return n itself
        if (n & (n - 1)) == 0:
            return n

        # Find the position of the highest set bit in n
        pos = 0
        while n > 0:
            n >>= 1
            pos += 1

        # Create a number with all bits set up to the position found
        mask = (1 << pos) - 1

        # Return the smallest number with all bits set that is greater than or equal to n
        return (mask | ((1 << pos) - 1))
