class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(len(nums)))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        for i, num in enumerate(nums):
            for j in range(1, int(threshold / num) + 1):
                if num * j > threshold:
                    break
                union(i, nums.index(num * j))

        return len(set(find(i) for i in range(len(nums))))
