from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Create adjacency lists for both sets of currency pairs
        graph1 = {}
        for i in range(len(pairs1)):
            start, target = pairs1[i]
            if start not in graph1:
                graph1[start] = []
            graph1[start].append((target, rates1[i]))

        graph2 = {}
        for i in range(len(pairs2)):
            start, target = pairs2[i]
            if start not in graph2:
                graph2[start] = []
            graph2[start].append((target, rates2[i]))

        # Function to perform DFS on a graph to find the maximum amount
        def dfs(graph, start, end, visited, current_rate):
            if start == end:
                return current_rate
            max_amount = 0
            for neighbor, rate in graph.get(start, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    max_amount = max(max_amount, dfs(graph, neighbor, end, visited, current_rate * rate))
                    visited.remove(neighbor)
            return max_amount

        # Calculate the maximum amount for each possible path through both graphs
        max_amount = 0
        for start, _ in graph1.get(initialCurrency, []):
            visited = {initialCurrency}
            amount_day1 = dfs(graph1, initialCurrency, start, visited, 1.0)
            for target, _ in graph2.get(start, []):
                visited = {start}
                amount_day2 = dfs(graph2, start, target, visited, 1.0)
                max_amount = max(max_amount, amount_day1 * amount_day2)

        return max_amount
