    def numberOfSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        count = defaultdict(int)
        result = 0

        for i in range(n-1, -1, -1):
            target = {}
            for j in range(i+1, n):
                if nums[j] not in target:
                    target[nums[j]] = []
                target[nums[j]].append(j)

            for num in count:
                if num * nums[i] in target:
                    for index in target[num * nums[i]]:
                        if index - i > 1:
                            result = (result + count[num]) % MOD

            count[nums[i]] += 1

        return result
