class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        if k >= n or k == 0:
            return pow(m, n, MOD)

        dp = [[0] * (k + 1) for _ in range(n + 1)]
        prefix_sum = [[0] * (k + 1) for _ in range(n + 1)]

        dp[1][0] = m
        prefix_sum[1][0] = m

        for length in range(2, n + 1):
            for exactly_k in range(1, min(length, k + 1)):
                dp[length][exactly_k] = (m - 1) * prefix_sum[length - 1][exactly_k - 1]
                dp[length][exactly_k] %= MOD

                prefix_sum[length][exactly_k] = (prefix_sum[length - 1][exactly_k] + dp[length][exactly_k]) % MOD

        return dp[n][k]
