class Solution:
    def calculateScore(self, s: str) -> int:
        n = len(s)
        score = 0
        marked = [False] * n

        for i in range(n):
            if marked[i]:
                continue

            target = chr(ord('z') + ord('a') - ord(s[i]))
            j = i - 1
            while j >= 0:
                if not marked[j] and s[j] == target:
                    score += i - j
                    marked[i] = True
                    marked[j] = True
                    break
                j -= 1

        return score
