class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        # Initialize pointers for both strings
        i, j = 0, 0
        star_index = -1
        match_index = -1

        while i < len(s):
            if j < len(p) and (s[i] == p[j] or p[j] == '?'):
                i += 1
                j += 1
            elif j < len(p) and p[j] == '*':
                star_index = j
                match_index = i
                j += 1
            elif star_index != -1:
                j = star_index + 1
                match_index += 1
                i = match_index
            else:
                return False

        # Check if remaining characters in pattern are all '*'
        while j < len(p) and p[j] == '*':
            j += 1

        return j == len(p)
