    return s == s[::-1]

def shortest_palindrome_path(N, grid):
    result = [[-1] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if i == j:
                result[i][j] = 0
                continue

            queue = deque([(i, j, 0)])
            visited = set()

            while queue:
                x, y, dist = queue.popleft()

                if (x, y) in visited:
                    continue
                visited.add((x, y))

                if x == j:
                    result[i][j] = dist
                    break

                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy

                    if 0 <= nx < N and 0 <= ny < N and grid[x][y] != '-' and grid[nx][ny] != '-':
                        new_dist = dist + 1
                        if is_palindrome(grid[x][y] + grid[nx][ny]):
                            queue.append((nx, ny, new_dist))

    return result

