from collections import deque

def min_front_kicks(H, W, grid, start, end):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    def bfs(start, end):
        queue = deque([start])
        visited = set([start])
        kicks = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()

                if (x, y) == end:
                    return kicks

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    if is_valid(nx, ny) and (nx, ny) not in visited:
                        if grid[nx][ny] == '.':
                            visited.add((nx, ny))
                            queue.append((nx, ny))
                        else:
                            # Perform a front kick
                            for kdx, kdy in directions:
                                for step in range(1, 3):
                                    nxx, nyy = nx + kdx * step, ny + kdy * step
                                    if is_valid(nxx, nyy):
                                        if grid[nxx][nyy] == '#':
                                            grid[nxx][nyy] = '.'
                                            visited.add((nxx, nyy))
                                            queue.append((nxx, nyy))
                            kicks += 1
                            break
            if kicks > 0:
                break

        return kicks

    return bfs(start, end)

