def count_valid_placements(H, W, grid):
    def count_type_A():
        return pow(4, count_A, MOD)

    def count_type_B():
        return pow(2, count_B, MOD)

    def count_valid_connections():
        # Check horizontal connections
        valid_horizontal = True
        for i in range(H):
            for j in range(W - 1):
                if (grid[i][j] == 'A' and grid[i][j + 1] != 'A') or \
                   (grid[i][j] == 'B' and grid[i][j + 1] != 'B'):
                    valid_horizontal = False
                    break
            if not valid_horizontal:
                break

        # Check vertical connections
        valid_vertical = True
        for j in range(W):
            for i in range(H - 1):
                if (grid[i][j] == 'A' and grid[i + 1][j] != 'A') or \
                   (grid[i][j] == 'B' and grid[i + 1][j] != 'B'):
                    valid_vertical = False
                    break
            if not valid_vertical:
                break

        return int(valid_horizontal and valid_vertical)

    count_A = sum(row.count('A') for row in grid)
    count_B = sum(row.count('B') for row in grid)

    total_ways = (count_type_A() * count_type_B()) % MOD
    valid_ways = total_ways * count_valid_connections()

    return valid_ways % MOD

def main():
    index = 0
    T = int(data[index])
    index += 1

    results = []
    for _ in range(T):
        H = int(data[index])
        W = int(data[index + 1])
        index += 2

        grid = data[index:index + H]
        index += H

        result = count_valid_placements(H, W, grid)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
