class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]

        def dfs(x, y, k):
            if x == m or y == n:
                return float('-inf')
            if k == 0:
                return coins[x][y]
            if dp[x][y][k] != float('-inf'):
                return dp[x][y][k]

            dp[x][y][k] = max(dfs(x + 1, y, k - 1), dfs(x, y + 1, k - 1)) + coins[x][y]
            return dp[x][y][k]

        return max(0, dfs(0, 0, 2))
