class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online_users = set(range(numberOfUsers))

        for event in sorted(events, key=lambda x: int(x[1])):
            event_type, timestamp, data = event

            if event_type == "OFFLINE":
                user_id = int(data)
                online_users.remove(user_id)

                # Remove mentions from this user's messages
                for i in range(len(online_users)):
                    mentions[i] -= data in online_users

            elif event_type == "MESSAGE":
                if "ALL" in data:
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                else:
                    mentioned_ids = set(int(id) for id in data.split() if id.startswith("id"))
                    for i in range(numberOfUsers):
                        if i in mentioned_ids:
                            mentions[i] += 1

        return mentions
