class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Sort the bottom-left triangle (including the middle diagonal)
        for i in range(n):
            diag = []
            for j in range(i, n):
                diag.append(grid[j][i])
            diag.sort(reverse=True)
            for j in range(i, n):
                grid[j][i] = diag[j - i]

        # Sort the top-right triangle
        for i in range(1, n):
            diag = []
            for j in range(i, n):
                diag.append(grid[i][j])
            diag.sort()
            for j in range(i, n):
                grid[i][j] = diag[j - i]

        return grid
