class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + points[i]

        def canAchieve(min_val, m):
            need_moves = 0
            for i in range(1, n + 1):
                if prefix_sum[i] - prefix_sum[max(0, i - min_val)] < min_val:
                    need_moves += min_val - (prefix_sum[i] - prefix_sum[max(0, i - min_val)])
                    if need_moves > m:
                        return False
            return True

        left, right = 0, max(points)
        while left < right:
            mid = (left + right + 1) // 2
            if canAchieve(mid, m):
                left = mid
            else:
                right = mid - 1
        return left
