class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        if n < 2 * k:
            return False

        for i in range(n - k + 1):
            seen = set()
            valid = True
            for j in range(i, n):
                if s[j] in seen:
                    valid = False
                    break
                seen.add(s[j])
                if len(seen) > k:
                    valid = False
                    break
            if valid:
                remaining = s[:i] + s[j+1:]
                if self.maxSubstringLength(remaining, k-1):
                    return True
        return False
