class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        max_length = 0

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for dx, dy in directions:
                        length = 1
                        x, y = i + dx, j + dy
                        while 0 <= x < n and 0 <= y < m:
                            if grid[x][y] == (length % 2) * 2 + 1:
                                length += 1
                                x += dx
                                y += dy
                            else:
                                break
                        # Check for 90-degree turn
                        nx, ny = x + dy, y - dx
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == (length % 2) * 2 + 1:
                            length += 1
                            x, y = nx, ny
                            while 0 <= x < n and 0 <= y < m:
                                if grid[x][y] == (length % 2) * 2 + 1:
                                    length += 1
                                    x += dx
                                    y += dy
                                else:
                                    break
                        max_length = max(max_length, length)

        return max_length
