class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        target_sum = sum(nums[:x])
        current_sum = target_sum
        min_operations = float('inf')
        count = 1

        for i in range(x, n):
            current_sum += nums[i]
            current_sum -= nums[i - x]
            if i >= (k - 1) * x:
                if count == k:
                    min_operations = min(min_operations, abs(target_sum - current_sum))
                else:
                    count += 1

        return min_operations if min_operations != float('inf') else -1
