from typing import *
from collections import *

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        dp = [[[-1] * 2 for _ in range(n)] for _ in range(k + 1)]

        def dfs(i, alt_sum, prod):
            if i == n:
                return 0 if alt_sum == k else float('-inf')
            if dp[alt_sum][i][prod] != -1:
                return dp[alt_sum][i][prod]

            # Option 1: Include nums[i]
            include = 0
            if alt_sum % 2 == 0:
                include = nums[i] * dfs(i + 1, alt_sum + nums[i], prod * nums[i])
            else:
                include = nums[i] * dfs(i + 1, alt_sum - nums[i], prod * nums[i])

            # Option 2: Exclude nums[i]
            exclude = dfs(i + 1, alt_sum, prod)

            # Choose the option that maximizes the product while staying within the limit
            result = max(include, exclude)
            if result > limit:
                result = exclude

            dp[alt_sum][i][prod] = result
            return result

        result = dfs(0, 0, 1)
        return result if result != float('-inf') else -1
