class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k > self.count(n):
            return []

        result = []
        numbers = list(range(1, n + 1))
        parity = 0

        while len(numbers) > 0:
            size = len(numbers)
            block_size = factorial(size - 1)

            if k % 2 == 1:
                index = (k - 1) // block_size
            else:
                index = k // block_size

            result.append(numbers.pop(index))
            k -= index * block_size
            parity = 1 - parity

        return result

    def count(self, n: int) -> int:
        if n % 2 == 0:
            return factorial(n) // (factorial(n // 2) ** 2)
        else:
            return factorial(n) // (factorial((n - 1) // 2) * factorial((n + 1) // 2))
