class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        result = [0] * n

        for i in range(n):
            remaining_words = words[:i] + words[i+1:]
            if len(remaining_words) < k:
                continue

            counter = Counter()
            for word in remaining_words:
                for j in range(min(k, len(word))):
                    counter[word[:j+1]] += 1

            max_length = 0
            for prefix, count in counter.items():
                if count >= k:
                    max_length = max(max_length, len(prefix))

            result[i] = max_length

        return result
